// @ts-ignore
import { useLocaleInfo } from "framer"
import { clamp } from "framer-motion"
import { useEffect, useState, useTransition } from "react"
import { SearchResultTitleType } from "./SearchModal.tsx"
import {
    getCachedIndex,
    isDefaultLocaleId,
    setCachedIndex,
} from "./cachedIndex.ts"
import { fakeResults } from "./fakeResults.ts"
import { distance } from "./fuzzySearch.ts"
import type { SearchIndexItem, SearchItem, SearchStatus } from "./types.ts"
import {
    createLogger,
    localStorageDebugFlag,
    safeDocument,
    safeWindow,
    stripLocaleSlugFromPath,
    yieldToMain,
} from "./utils.ts"

const { log, time, timeEnd } = createLogger(localStorageDebugFlag)

export interface SearchIndex {
    [url: string]: SearchIndexItem
}

interface SearchSettings {
    minimumScore?: number
    urlScope?: string
    titleType: SearchResultTitleType
}

const splitWordsRegex = (() => {
    try {
        // Regex lookbehind is used to ignore ampersands when splitting
        // words. For example "H&M" will not be split and is considered as
        // one word, but "H & M" will be split.
        // However, some browsers (like Safari iOS 15) don't support
        // lookbehind and will crash. When it's not supported, fallback to
        // a safer regex that always splits ampersands.
        const regex = /[\s.,;!?\p{P}\p{Z}]+(?<!\p{L}&)(?!&\p{L})/u
        "".split(regex)
        return regex
    } catch {
        log("Falling back to regex without lookbehind")
        return /[\s.,;!?\p{P}\p{Z}]+/u
    }
})()

function splitWords(text: string) {
    return text.split(splitWordsRegex)
}

function getUniqueWords(str: string) {
    const words = splitWords(str).filter(
        (word) => word.trim() && word.length > 0
    )

    return new Set(words)
}

const normalizeRegex = /[\u0300-\u036f]/g

/**
 * Replace accented characters with equivilant non-accented versions and
 * make everything lowercase.
 */
function getNormalizedString(text: string | string[]) {
    if (Array.isArray(text)) {
        return text.map(getNormalizedString)
    }

    return (
        text
            .normalize("NFD")
            // From: https://stackoverflow.com/a/37511463
            .replace(normalizeRegex, "")
            .toLowerCase()
    )
}

const normalizedItemCache = new WeakMap<SearchIndexItem, SearchIndexItem>()

function getNormalizedItemFromCache(item: SearchIndexItem): SearchIndexItem {
    const cached = normalizedItemCache.get(item)
    if (cached) return cached
    const normalizedItem = getNormalizedItem(item)
    normalizedItemCache.set(item, normalizedItem)
    return normalizedItem
}

function getNormalizedItem(item: SearchIndexItem) {
    const normalizedItem = {}

    for (const key in item) {
        if (item.hasOwnProperty(key)) {
            const value = item[key]

            if (typeof value === "string") {
                normalizedItem[key] = getNormalizedString(value)
                continue
            }

            if (Array.isArray(value)) {
                normalizedItem[key] = getNormalizedString(value)
                continue
            }

            normalizedItem[key] = value
        }
    }

    return normalizedItem as SearchIndexItem
}

interface MatchRange {
    start: number
    end: number
}

interface SearchIndexItemMatch {
    title: MatchRange
    description: MatchRange
}

function getMatchRange(
    currentRange: MatchRange,
    start: number,
    end: number
): MatchRange {
    const result = { ...currentRange }

    if (start < result.start) {
        result.start = start
    }

    if (end > result.end) {
        result.end = end
    }

    return result
}

/**
 * Score index item based on the contents of it's fields such as title, description, headings etc.
 *
 * Note that this does not normalize the item or query. Normalization is expected to happen
 * before passing the data into this.
 */
function getScoreForSearchIndexItem(
    item: SearchIndexItem,
    query: string,
    words: Set<string>,
    fullQuery: string
): { score: number; match: SearchIndexItemMatch } {
    let score = 0

    const match: SearchIndexItemMatch = {
        title: { start: Infinity, end: 0 },
        description: { start: Infinity, end: 0 },
    }

    const urlWords = getUniqueWords(item.url)

    // Match query based on words in the URL so that random strings inside
    // other strings are not matched.
    if (urlWords.has(query)) {
        score += 10
    }

    // Really boost single word queries that match single word URLs.
    if (
        words.size === 1 &&
        urlWords.size === 1 &&
        urlWords.values().next().value === query
    ) {
        score += score * 5
    }

    // Score shorter URLs higher so `/pricing` is before `/lala/pricing`.
    if (score > 0) {
        const splitLength = item.url.split("/").length
        score += clamp(10 - splitLength, 0, splitLength)
    }

    const titleWords = getUniqueWords(item.title)

    // Prefer full word matches in the title.
    if (titleWords.has(query)) {
        score += 10
    }

    const titleIndex = item.title.indexOf(query)

    if (titleIndex !== -1) {
        score += 10

        // TODO: Matches are currently not used, but they can be used in the
        // future to add text highlighting.
        match.title = getMatchRange(
            match.title,
            titleIndex,
            titleIndex + query.length
        )
    }

    // If the full query is close to being the heading, score this highly as
    // the user is most likely looking for that exact title.
    if (distance(item.title, fullQuery) <= 2) {
        score += score * 10
    }

    // Fuzzy match full words in the title.
    for (const titleWord of titleWords) {
        const distanceScore = distance(query, titleWord)

        // Small distance score helps with small typos.
        if (distanceScore <= 2) {
            score += 10
        }
    }

    const headings = [
        ...item.h1,
        ...item.h2,
        ...item.h3,
        ...item.h4,
        ...item.h5,
        ...item.h6,
    ]

    for (const heading of headings) {
        const headingWords = getUniqueWords(heading)

        // If the full query is close to being the heading, score this highly as
        // the user is most likely looking for that exact title.
        if (distance(heading, fullQuery) <= 2) {
            score += score * 10
        }

        // Bias headings that start with the query as this helps when
        // you know the title you are searching for.
        if (heading.startsWith(query)) {
            score += 10
        }

        if (headingWords.has(query)) {
            score += 10
        }

        if (heading.includes(query)) {
            score += 1
        }

        // Fuzzy match full words in headings.
        for (const headingWord of headingWords) {
            const distanceScore = distance(query, headingWord)

            if (distanceScore <= 2) {
                score += 1
            }
        }
    }

    const descriptionIndex = item.description.indexOf(query)

    if (descriptionIndex !== -1) {
        score += 10

        match.description = getMatchRange(
            match.description,
            descriptionIndex,
            descriptionIndex + query.length
        )
    }

    for (const p of item.p) {
        if (p.includes(query)) {
            score += 0.5
        }
    }

    for (const codeblock of item.codeblock) {
        // If the full query is close to being the codeblock, score this highly as
        // the user is most likely looking for that exact code.
        if (distance(codeblock, fullQuery) <= 2) {
            score *= 10
        }

        if (codeblock.includes(fullQuery)) {
            score += 10
        }

        if (codeblock.includes(query)) {
            score += 0.5
        }
    }

    return { score, match }
}

function getSearchIndexItemScore(
    item: SearchIndexItem,
    normalizedQuery: string
): number {
    const normalizedItem = getNormalizedItemFromCache(item)
    const queryWords = getUniqueWords(normalizedQuery)

    let total = 0

    for (const queryWord of queryWords) {
        const { score } = getScoreForSearchIndexItem(
            normalizedItem,
            queryWord,
            queryWords,
            normalizedQuery
        )

        total += score
    }

    return total
}

function useRawSearch(
    index: SearchIndex,
    query: string,
    settings?: SearchSettings
): { results: SearchItem[] } {
    const [results, setResults] = useState<SearchItem[] | null>(null)
    const [, startTransition] = useTransition()

    useEffect(() => {
        const abortController = new AbortController()

        executeRawSearch(index, query, settings, abortController.signal)
            .then((res) => {
                if (!abortController.signal.aborted) {
                    startTransition(() => {
                        setResults(res)
                    })
                }
            })
            .catch((err) => {
                if (err.name !== "AbortError") {
                    console.error("Search failed:", err)
                }
            })

        return () => {
            abortController.abort()
        }
    }, [index, query])

    return { results: results ?? [] }
}

const QUANTUM = 32 // ms, 2*16ms (2 frames on 60 hz)

async function executeRawSearch(
    index: SearchIndex,
    query: string,
    settings?: SearchSettings,
    signal?: AbortSignal
) {
    const path = safeWindow?.location.pathname

    time("query")

    const normalizedQuery = getNormalizedString(query)
    const results: SearchItem[] = []

    const items = Object.values(index)
    let deadline = performance.now() + QUANTUM

    async function yieldToMainIfNecessary() {
        if (performance.now() >= deadline) {
            await yieldToMain()
            deadline = performance.now() + QUANTUM
        }
    }

    for (let i = 0; i < items.length; ++i) {
        if (performance.now() >= deadline) {
            await yieldToMainIfNecessary()
            deadline = performance.now() + QUANTUM
        }
        if (signal?.aborted) return []

        const item = items[i]
        const score = getSearchIndexItemScore(item, normalizedQuery)

        if (
            score > (settings.minimumScore || 0) &&
            (!path || item.url !== path)
        ) {
            const heading = item.h1.length && item.h1[0]
            const title =
                settings?.titleType === SearchResultTitleType.Title
                    ? item.title
                    : heading
                      ? heading
                      : item.title

            // Convert index item to result item.
            results.push({
                url: item.url,
                title,
                description: item.description,
                body: [...item.p, item.codeblock].join(" "),
                score,
            })
        }
    }

    await yieldToMainIfNecessary()
    if (signal?.aborted) return []
    const sorted = results.sort((itemA, itemB) => itemB.score - itemA.score)

    timeEnd("query")

    await yieldToMainIfNecessary()
    if (signal?.aborted) return []

    return results.slice(0, 20)
}

function getIndexedScopedToUrl(
    index: SearchIndex,
    rawUrlScope: string,
    localeSlug: string | undefined
): SearchIndex {
    const scopedIndex = {}
    const baseScopeUrlHasVariable = rawUrlScope.includes(":")
    const urlUpToPathVariable = rawUrlScope.split(":")[0]
    const urlScope = urlUpToPathVariable.length > 1 ? urlUpToPathVariable : ""

    for (const url in index) {
        const strippedURL = stripLocaleSlugFromPath(url, localeSlug)
        if (!strippedURL.startsWith(urlScope)) {
            continue
        }
        if (baseScopeUrlHasVariable && url.length <= urlScope.length) {
            continue
        }

        scopedIndex[url] = index[url]
    }

    return scopedIndex
}

interface SetSearchIndexOptions {
    // Disable URL scoping when setting the index.
    ignoreScope: boolean
}

export function useSearch(
    query: string,
    settings?: SearchSettings
): { results: SearchItem[]; status: SearchStatus } {
    const [searchIndex, _setSearchIndex] = useState<SearchIndex>({})
    const [status, setStatus] = useState<SearchStatus>("loading")
    const { results } = useRawSearch(searchIndex, query, settings)
    const { activeLocale } = useLocaleInfo()
    const localeId = activeLocale?.id

    // Seperate setter function so that the URL scope is always applied
    // to indexes loaded from either the cache or network.
    function setSearchIndex(
        index: SearchIndex,
        options: SetSearchIndexOptions = { ignoreScope: false }
    ) {
        let scopedIndex = index

        if (settings.urlScope && !options.ignoreScope) {
            scopedIndex = getIndexedScopedToUrl(
                index,
                settings.urlScope,
                activeLocale?.slug
            )
            log("Using URL scope", settings.urlScope)
        }

        _setSearchIndex(scopedIndex)
    }

    useEffect(() => {
        async function loadSearchIndex() {
            setStatus("loading")

            const baseUrl = getBaseUrl("framer-search-index")
            if (!baseUrl) {
                setStatus("no-meta-tag-found")
                setSearchIndex(fakeResults, { ignoreScope: true })
                log("No meta tag found")
                return
            }

            const cacheResult = await getCachedIndex(localeId, baseUrl)
            if (cacheResult.status === "fresh") {
                setSearchIndex(cacheResult.searchIndex)
                setStatus("success")
                log("Using fresh cached index")
                return
            }
            if (cacheResult.status === "stale") {
                setSearchIndex(cacheResult.searchIndex)
                setStatus("loading-with-cache")
                log("Using stale cached index while loading a fresh one")
            }

            const searchIndexUrl = getSearchIndexUrl(baseUrl, localeId)
            const response = await fetch(searchIndexUrl)

            if (response.ok) {
                const downloadedIndex = (await response.json()) as SearchIndex
                setSearchIndex(downloadedIndex)
                setCachedIndex(localeId, downloadedIndex, baseUrl)
                setStatus("success")
                log("Using downloaded index")
                return
            }

            // Our "sites" CDN currently returns 403s for missing files.
            const isNotFound =
                response.status === 403 || response.status === 404
            if (!isNotFound) {
                throw new Error(response.statusText)
            }

            // Index is likely still being generated.
            log("Index not found")

            const fallbackBaseUrl = getBaseUrl("framer-search-index-fallback")
            if (!fallbackBaseUrl) {
                if (cacheResult.status === "miss") {
                    setStatus("pending-index-generation")
                    log("No fallback, no cache")
                } else {
                    setStatus("success")
                    log("No fallback, using cache")
                }
                return
            }

            // If we're here, cache is missing or stale.
            // If it's stale but it's our fallback index, we can use it.
            if (
                cacheResult.status === "stale" &&
                cacheResult.indexHash === fallbackBaseUrl
            ) {
                setStatus("success")
                log("Using cached fallback index")
                return
            }

            const fallbackSearchIndexUrl = getSearchIndexUrl(
                fallbackBaseUrl,
                localeId
            )
            const fallbackResponse = await fetch(fallbackSearchIndexUrl)

            if (fallbackResponse.ok) {
                const downloadedIndex =
                    (await fallbackResponse.json()) as SearchIndex
                setSearchIndex(downloadedIndex)
                setCachedIndex(localeId, downloadedIndex, fallbackBaseUrl)
                setStatus("success")
                log("Using downloaded fallback index")
                return
            }

            if (cacheResult.status === "miss") {
                setStatus("pending-index-generation")
                log("Fallback failed, no cache")
            } else {
                setStatus("success")
                log("Fallback failed, using cache")
            }
        }

        loadSearchIndex().catch((error) => {
            // TODO: Check for error type here. If it's a network error,
            // we could do a few retries.
            setStatus("error")
            log("Failed to load search index", error)
        })
    }, [localeId])

    log({ status, results })

    return { results, status }
}

function getBaseUrl(name: string): string | undefined {
    return safeDocument
        ?.querySelector(`meta[name="${name}"]`)
        ?.getAttribute("content")
}

function getSearchIndexUrl(baseURL: string, localeId: string | undefined) {
    if (isDefaultLocaleId(localeId)) return baseURL
    return baseURL.replace(".json", `-${localeId}.json`)
}
